import { test, expect } from '@playwright/test';

test.describe('Image Gallery Lightbox', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/gallery');
  });

  test('should open lightbox when clicking an image in gallery', async ({ page }) => {
    // Verify gallery container is visible
    const gallery = page.getByRole('region', { name: /gallery/i });
    await expect(gallery).toBeVisible();

    // Get the first image and click it
    const firstImage = page.getByRole('img', { name: /image 1/i });
    await expect(firstImage).toBeVisible();
    await firstImage.click();

    // Verify lightbox overlay appears
    const lightboxOverlay = page.getByRole('dialog', { name: /lightbox/i });
    await expect(lightboxOverlay).toBeVisible();

    // Verify image is displayed in lightbox
    const lightboxImage = page.getByRole('img', { name: /image 1/i });
    await expect(lightboxImage).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify lightbox has correct dimensions
    const lightboxRect = await lightboxOverlay.boundingBox();
    expect(lightboxRect.width).toBeGreaterThan(0);
    expect(lightboxRect.height).toBeGreaterThan(0);
  });

  test('should close lightbox when clicking close button or pressing escape', async ({ page }) => {
    // Get the first image and open lightbox
    const firstImage = page.getByRole('img', { name: /image 1/i });
    await firstImage.click();

    // Verify lightbox is open
    const lightboxOverlay = page.getByRole('dialog', { name: /lightbox/i });
    await expect(lightboxOverlay).toBeVisible();

    // Close lightbox using the close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify lightbox is closed
    await expect(lightboxOverlay).not.toBeVisible();

    // Open lightbox again
    await firstImage.click();
    await expect(lightboxOverlay).toBeVisible();

    // Close lightbox using escape key
    await page.keyboard.press('Escape');
    await expect(lightboxOverlay).not.toBeVisible();
  });
});
